 for(const p of[[-.37,-.012,.035],[.09,-.010,.040],[.25,-.103,.035],[-.27,.098,.033],[.33,.204,.035],[.50,-.08,.032]])c.organelleMito(a('mitochondria'),p,[.050,.021,.019]);

