 for(const[key,x,y]of locs){const p=[x,y,0],parent=a(key);parent.userData.divisionExample='2n=4; X=duplicado; bastão=simples';if(key==='cytokinesis'){for(const s of[-1,1]){stageCell(c,parent,[x+s*.079,y,0],.074,.11);fourChromosomes(c,parent,[x+s*.079,y,0],false,.065)}}else{stageCell(c,parent,p,.145,.13);if(['prophase','prometaphase'].includes(key)){fourChromosomes(c,parent,p,true,.09);if(key==='prophase')c.loop(parent,[x,y,.015],.10,.085,.004,C.purple);else spindle(c,parent,p,[[x-.045,y+.02,.035],[x+.045,y-.03,.035]])}else if(key==='metaphase'){const targets=[];for(let i=0;i<4;i++){const t=[x,y-.081+i*.054,.035];c.chromosome(parent,t,.043,i%2?C.orange:C.blue,true);targets.push(t)}spindle(c,parent,p,targets)}else{for(const s of[-1,1])for(let i=0;i<4;i++)c.chromosome(parent,[x+s*.075,y-.066+i*.044,.035],.034,i%2?C.orange:C.blue,false);if(key==='telophase')for(const s of[-1,1])c.loop(parent,[x+s*.075,y,.04],.046,.095,.004,C.purple);else for(const s of[-1,1])c.arrow(parent,[x+s*.02,y,.06],[x+s*.10,y,.06],C.green)}}if(key!=='cytokinesis')for(const s of[-1,1])c.ball(a('centrosomes'),[x+s*.135,y,.035],[.012,.012,.010],C.gold)}
